mkdir -p /tmp/e2e/rec && cat > /tmp/e2e/rec.mjs <<'EOF'
// rec.mjs <outDir> <seconds>: CDP screencast of the current tab; frames + timestamps for ffmpeg concat.
import fs from "node:fs";
const [outDir, secs = "5"] = process.argv.slice(2);
fs.mkdirSync(outDir, { recursive: true });
const page = (await (await fetch("http://127.0.0.1:9333/json")).json()).find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0; const frames = [];
const send = (method, params = {}) => ws.send(JSON.stringify({ id: ++id, method, params }));
ws.addEventListener("message", (e) => {
  const m = JSON.parse(e.data);
  if (m.method === "Page.screencastFrame") {
    const f = `${outDir}/f${String(frames.length).padStart(5, "0")}.jpg`;
    fs.writeFileSync(f, Buffer.from(m.params.data, "base64"));
    frames.push({ f, t: m.params.metadata.timestamp });
    send("Page.screencastFrameAck", { sessionId: m.params.sessionId });
  }
});
send("Page.startScreencast", { format: "jpeg", quality: 85, maxWidth: 1280, maxHeight: 1000, everyNthFrame: 1 });
await new Promise((r) => setTimeout(r, Number(secs) * 1000));
send("Page.stopScreencast");
const end = Date.now() / 1000;
const lines = frames.map((fr, i) => `file '${fr.f}'\nduration ${((frames[i + 1]?.t ?? end) - fr.t).toFixed(3)}`);
if (frames.length) lines.push(`file '${frames.at(-1).f}'`);
fs.writeFileSync(`${outDir}/list.txt`, lines.join("\n") + "\n");
console.log(`${frames.length} frames -> ${outDir}/list.txt`);
ws.close(); process.exit(0);
EOF
